import{_ as i,o as n,c as t,ae as r}from"./chunks/framework.BvHJbMD4.js";const m=JSON.parse('{"title":"Die Besetzung (Cast)","description":"","frontmatter":{},"headers":[],"relativePath":"cast.md","filePath":"cast.md"}'),s={name:"cast.md"};function a(l,e,o,u,c,h){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="die-besetzung-cast" tabindex="-1">Die Besetzung (Cast) <a class="header-anchor" href="#die-besetzung-cast" aria-label="Permalink to &quot;Die Besetzung (Cast)&quot;">​</a></h1><p>Für unsere Mockumentary konnten wir zwei der intensivsten Schauspieler des deutschsprachigen Kinos (fiktiv) gewinnen. Ihre Aufgabe: Die moralischen Grauzonen der Geschichte mit Leben zu füllen.</p><h2 id="august-diehl-als-helmut-horten" tabindex="-1">August Diehl als <em>Helmut Horten</em> <a class="header-anchor" href="#august-diehl-als-helmut-horten" aria-label="Permalink to &quot;August Diehl als *Helmut Horten*&quot;">​</a></h2><p>August Diehl verkörpert den jungen Helmut Horten mit einer beunruhigenden Präzision.</p><ul><li><strong>Die Rolle:</strong> Ein Mann, der keine Gefühle zeigt, außer wenn er Bilanzen liest. Er sieht die Arisierung nicht als Verbrechen, sondern als logistische Herausforderung.</li><li><strong>Zitat vom Set:</strong> <em>&quot;Horten ist kein Bösewicht im klassischen Sinne. Er ist ein Vakuum, das alles Geld der Welt ansaugt.&quot;</em></li></ul><h2 id="oliver-masucci-als-bankier-schreck" tabindex="-1">Oliver Masucci als <em>Bankier Schreck</em> <a class="header-anchor" href="#oliver-masucci-als-bankier-schreck" aria-label="Permalink to &quot;Oliver Masucci als *Bankier Schreck*&quot;">​</a></h2><p>Masucci bringt die notwendige Wucht und den zynischen Humor für die Rolle des hessischen Strippenziehers mit.</p><ul><li><strong>Die Rolle:</strong> Der Mann fürs Grobe im feinen Zwirn. Er ist der emotionale Gegenpol zu Horten – laut, gierig und immer mit einem Glas Schnaps in der Hand.</li><li><strong>Hintergrund:</strong> Er ist das personifizierte schlechte Gewissen, das gar kein Gewissen hat.</li></ul><hr><p><em>Weitere Ankündigungen zum Cast folgen in Kürze (u.a. die Besetzung für die schillernde Heidi Horten).</em></p>',10)])])}const g=i(s,[["render",a]]);export{m as __pageData,g as default};
